const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = path.resolve(__dirname, '../..');
const LANG_PATH = path.join(ROOT, 'language/en.json');
const CONFIG_PATH = path.join(ROOT, 'config.js');

// Indentation standards (2-space model)
const INDENT_SIZE = 2;
const TOC_INDENT = 8;    // <li> inside .doc-sidebar > ol/ul (Level 4 child)
const BODY_INDENT = 6;   // <section> inside .doc-main (Level 3 child)

/** Helper to generate indentation spaces based on level offset */
const pad = (base, level = 0) => ' '.repeat(base + level * INDENT_SIZE);

const APPS = [
  {
    id: 'shape',
    profile: 'ui/profile-shape.json',
    page: 'easyshape5000/doc/parameters.html',
    skipOps: ['pattern', 'unassigned']
  },
  {
    id: 'trace',
    profile: 'ui/profile-trace.json',
    page: 'easytrace5000/doc/parameters.html',
    skipOps: []
  }
];

const TOC_BEGIN = '<!-- PARAMS-TOC:BEGIN - generated by build-doc-params.js, do not edit -->';
const TOC_END = '<!-- PARAMS-TOC:END -->';
const BODY_BEGIN = '<!-- PARAMS:BEGIN - generated by build-doc-params.js, do not edit -->';
const BODY_END = '<!-- PARAMS:END -->';

const esc = s => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const read = p => JSON.parse(fs.readFileSync(p, 'utf8'));

/**
 * CAMConfig as the pages see it: config.js run in a context of its own, the way the
 * field worker runs it. It reads no DOM while it loads.
 */
function loadConfig() {
  const sandbox = { console };
  sandbox.window = sandbox;
  sandbox.self = sandbox;
  vm.createContext(sandbox);
  vm.runInContext(fs.readFileSync(CONFIG_PATH, 'utf8'), sandbox, { filename: 'config.js' });
  return sandbox.CAMConfig;
}

/**
 * Every caption comes from en.json, resolved the way the app resolves it:
 * apps.<app>.<key> first, then <key>. The profiles hold ids only. A key en.json
 * lacks is recorded and fails the run, because the app would show the raw key.
 * @returns {Function} (...segments) => string
 */
function captions(lang, profile, missing, appId) {
  // Same scope id as LanguageManager.setApp.
  const scope = profile.meta.app.toLowerCase().replace(/[^a-z0-9]/g, '');
  const resolve = (node, parts) => parts.reduce((n, p) => (n !== null && typeof n === 'object' && Object.hasOwn(n, p) ? n[p] : undefined), node);
  return (...parts) => {
    const keys = parts.map(String);
    const hit = resolve(lang.apps?.[scope], keys) ?? resolve(lang, keys);
    if (typeof hit === 'string') return hit;
    missing.push(`${appId}: ${keys.join('.')}`);
    return keys.join('.');
  };
}

/** Same rule as InputRenderer: an option that carries a label is a name. */
function optionCaption(def, name, value, text) {
  const option = Array.isArray(def?.options) ? def.options.find(o => String(o.value) === String(value)) : null;
  return option?.label ?? text('params', name, 'options', value);
}

/**
 * A field shows only when every clause of its conditional can hold. One that names
 * a field the form does not have, or asks a select for a value it does not offer
 * (pocketStrategy:raster while the select offers offset alone), never shows, so it
 * is left out rather than documented.
 */
function reachable(def, defs) {
  if (!def.conditional) return true;
  return String(def.conditional).split('&&').every(part => {
    const [key, values] = part.trim().replace(/^!/, '').split(':');
    const ref = defs[key];
    if (!ref) return false;
    if (!values || !Array.isArray(ref.options)) return true;
    return values.split(',').some(v => ref.options.some(o => String(o.value) === v));
  });
}

/** Stage order is the union of every chain's stage list, in chain order. */
function stageOrder(profile) {
  const seen = [];
  for (const chain of Object.values(profile.chains || {})) {
    for (const s of chain.stages || []) if (!seen.includes(s)) seen.push(s);
  }
  return seen;
}

/** Parameters this app actually exposes, keyed stage -> category -> [param]. */
function collect(profile, skipOps) {
  const defs = profile.parameters || {};
  const out = new Map();
  for (const [name, def] of Object.entries(defs)) {
    if (name.startsWith('_')) continue;
    if (!def || typeof def !== 'object' || !def.stage) continue;
    if (!reachable(def, defs)) continue;

    const ops = def.operationTypes == null
      ? null
      : (Array.isArray(def.operationTypes) ? def.operationTypes : [def.operationTypes]);
    if (ops && ops.length && ops.every(o => skipOps.includes(o))) continue;

    const stage = def.stage;
    const category = def.category || 'general';
    if (!out.has(stage)) out.set(stage, new Map());
    const cats = out.get(stage);
    if (!cats.has(category)) cats.set(category, []);
    cats.get(category).push({ name, def, ops });
  }
  return { grouped: out, defs };
}

/**
 * The Machine Settings form, merged the way CamCore.machineSchema merges it: the
 * app's deltas over CAMConfig.machineParameters, per entry, where null deletes. An
 * entry without a type is seed-only and never rendered. Its caption is its leaf.
 */
function collectMachine(config, profile) {
  const schema = { ...config.machineParameters };
  for (const [key, override] of Object.entries(profile.machineParameters || {})) {
    if (override === null) delete schema[key];
    else schema[key] = { ...schema[key], ...override };
  }
  const entries = [];
  const defs = {};
  for (const [key, def] of Object.entries(schema)) {
    if (!def.type) continue;
    const name = key.slice(key.lastIndexOf('.') + 1);
    defs[name] = def;
    entries.push({ name, def });
  }
  const grouped = new Map();
  for (const entry of entries) {
    if (!reachable(entry.def, defs)) continue;
    const category = entry.def.category || 'general';
    if (!grouped.has(category)) grouped.set(category, []);
    grouped.get(category).push(entry);
  }
  return { grouped, defs };
}

/**
 * What a picker offers when its list comes from data rather than the schema: the
 * shipped posts and laser profiles by name, or every caption a post may offer.
 */
function sourceValues(entry, config, lang) {
  const named = (dir, ids) => ids.map(id => {
    const file = path.join(ROOT, dir, `${id}.json`);
    const label = fs.existsSync(file) ? read(file).label : null;
    return { id, label };
  });
  switch (entry.def.source) {
    case 'processors':
      return named('export/processors', config.constants.setups);
    case 'laserProfiles':
      return named('export/profiles', config.constants.laserProfiles);
    default:
      return Object.keys(lang.params?.[entry.name]?.options || {}).map(id => ({ id, label: null }));
  }
}

function rangeCell(entry, text, values) {
  const def = entry.def;
  if (values) {
    const words = values.map(v => esc(v.label ?? text('params', entry.name, 'options', v.id)));
    // Device names may hold a slash of their own (RDWorks / Ruida).
    if (['processors', 'laserProfiles'].includes(def.source)) return words.join(', ');
    return `${words.join(' / ')} (as the post-processor offers)`;
  }
  if (Array.isArray(def.options)) {
    return def.options.map(o => esc(optionCaption(def, entry.name, o.value, text))).join(' / ');
  }
  if (def.type === 'checkbox') return 'on / off';
  if (def.min !== undefined || def.max !== undefined) {
    const unit = def.unit ? ' ' + esc(text('units', def.unit)) : '';
    if (def.min !== undefined && def.max !== undefined) return `${def.min} - ${def.max}${unit}`;
    return def.min !== undefined ? `&ge; ${def.min}${unit}` : `&le; ${def.max}${unit}`;
  }
  if (def.type === 'select') return 'tool library';
  return '&mdash;';
}

function defaultCell(entry, text, values) {
  const def = entry.def;
  if (values) {
    const hit = values.find(v => v.id === def.default);
    if (!hit || !['processors', 'laserProfiles'].includes(def.source)) return 'set by the post-processor';
    return esc(hit.label ?? text('params', entry.name, 'options', hit.id));
  }
  if (def.default === undefined || def.default === null || def.default === '') return '&mdash;';
  if (def.default === true) return 'on';
  if (def.default === false) return 'off';
  if (Array.isArray(def.options)) return esc(optionCaption(def, entry.name, def.default, text));
  return esc(def.default);
}

function appliesCell(entry, text) {
  if (!entry.ops || !entry.ops.length) return 'all operations';
  return entry.ops.map(o => esc(text('ops', o, 'label'))).join(', ');
}

/**
 * Conditionals are the single most common support question: a field that is
 * declared but gated reads to the user as a missing field.
 */
function conditionCell(def, defs, text) {
  const notes = [];
  if (def.conditional) {
    const nameOf = key => text('params', key, 'label');
    const human = String(def.conditional)
      .split('&&')
      .map(part => {
        const t = part.trim();
        if (t.startsWith('!')) return `${nameOf(t.slice(1))} is off`;
        const [k, v] = t.split(':');
        if (!v) return `${nameOf(k)} is on`;
        return `${nameOf(k)} is ${v.split(',').map(x => optionCaption(defs[k], k, x, text)).join(' or ')}`;
      })
      .join(' and ');
    notes.push(`Shown when ${human}`);
  }
  if (def.capability) notes.push('Shown when the post-processor supports it');
  return notes.map(n => `<br><span class="param-condition">${esc(n)}</span>`).join('');
}

function classCell(classes) {
  if (!Array.isArray(classes)) return '';
  return `<br><span class="param-condition">Machine class: ${esc(classes.join(', '))}</span>`;
}

function buildApp(app, lang, config) {
  const profile = read(path.join(ROOT, app.profile));
  const missing = [];
  const text = captions(lang, profile, missing, app.id);
  const params = collect(profile, app.skipOps);
  const machine = collectMachine(config, profile);

  // Indentation levels
  const pToc   = pad(TOC_INDENT);         // 8 spaces:  <li>
  const pSec   = pad(BODY_INDENT, 0);     // 6 spaces:  <section>
  const pSub   = pad(BODY_INDENT, 1);     // 8 spaces:  <h2>, <h3>, <p>, <table>
  const pGroup = pad(BODY_INDENT, 2);     // 10 spaces: <thead>, <tbody>
  const pRow   = pad(BODY_INDENT, 3);     // 12 spaces: <tr>
  const pCell  = pad(BODY_INDENT, 4);     // 14 spaces: <td>

  // Same order as the app's forms: ui.categories, undeclared ones last.
  const rank = c => {
    const i = profile.ui.categories.indexOf(c);
    return i < 0 ? Number.MAX_SAFE_INTEGER : i;
  };
  const sorted = cats => [...cats].sort((a, b) => rank(a[0]) - rank(b[0]));
  const toc = [];
  const body = [];

  const table = (category, head, rows) => {
    body.push(`${pSub}<h3>${esc(text('categories', category))}</h3>`);
    body.push(`${pSub}<table>`);
    body.push(`${pGroup}<thead>`);
    body.push(`${pRow}<tr>${head.map(h => `<th scope="col">${h}</th>`).join('')}</tr>`);
    body.push(`${pGroup}</thead>`);
    body.push(`${pGroup}<tbody>`);
    for (const cells of rows) {
      body.push(`${pRow}<tr>`);
      for (const cell of cells) body.push(`${pCell}<td>${cell}</td>`);
      body.push(`${pRow}</tr>`);
    }
    body.push(`${pGroup}</tbody>`);
    body.push(`${pSub}</table>`);
  };

  // Machine Settings first: they apply to every operation, and the workflow sets them first.
  const machineName = esc(text('panels', 'machine', 'title'));
  toc.push(`${pToc}<li><a href="#machine-settings" draggable="false">${machineName}</a></li>`);
  body.push(`${pSec}<section id="machine-settings">`);
  body.push(`${pSub}<h2>${machineName}</h2>`);
  body.push(`${pSub}<p>These apply to every operation. The defaults are the app's: a post-processor's setup can start a field at its own value, or lock it while it is selected. A post-processor's own fields, such as its start and end blocks, appear under it.</p>`);
  for (const [category, list] of sorted(machine.grouped)) {
    table(category, ['Setting', 'Values', 'Default', 'What it does'], list.map(entry => {
      const values = entry.def.source ? sourceValues(entry, config, lang) : null;
      return [
        `<strong>${esc(text('params', entry.name, 'label'))}</strong>${conditionCell(entry.def, machine.defs, text)}${classCell(entry.def.classes)}`,
        rangeCell(entry, text, values),
        defaultCell(entry, text, values),
        esc(text('params', entry.name, 'help'))
      ];
    }));
  }
  body.push(`${pSec}</section>`);
  body.push('');

  for (const stage of stageOrder(profile)) {
    if (!params.grouped.has(stage)) continue;
    const stageId = `stage-${stage}`;
    const stageName = esc(text('stages', stage, 'label'));
    toc.push(`${pToc}<li><a href="#${stageId}" draggable="false">${stageName}</a></li>`);

    body.push(`${pSec}<section id="${stageId}">`);
    body.push(`${pSub}<h2>${stageName}</h2>`);
    for (const [category, list] of sorted(params.grouped.get(stage))) {
      table(category, ['Parameter', 'Values', 'Default', 'Applies to', 'What it does'], list.map(entry => [
        `<strong>${esc(text('params', entry.name, 'label'))}</strong>${conditionCell(entry.def, params.defs, text)}${classCell(entry.def.machineClasses)}`,
        rangeCell(entry, text, null),
        defaultCell(entry, text, null),
        appliesCell(entry, text),
        esc(text('params', entry.name, 'help'))
      ]));
    }
    body.push(`${pSec}</section>`);
    body.push('');
  }

  return { toc: toc.join('\n'), body: body.join('\n'), missing };
}

function replaceRegion(text, begin, end, content, file) {
  const i = text.indexOf(begin);
  const j = text.indexOf(end);
  if (i === -1 || j === -1 || j < i) {
    console.error(`❌ ${file}: missing marker pair ${begin} / ${end}`);
    process.exit(1);
  }
  return text.slice(0, i + begin.length) + '\n' + content + '\n' + text.slice(j);
}

const lang = read(LANG_PATH);
const config = loadConfig();
const allMissing = [];
const writes = [];

for (const app of APPS) {
  const pagePath = path.join(ROOT, app.page);
  if (!fs.existsSync(pagePath)) {
    console.error(`❌ Target page not found: ${app.page}`);
    process.exit(1);
  }
  const built = buildApp(app, lang, config);
  allMissing.push(...built.missing);

  let html = fs.readFileSync(pagePath, 'utf8');
  html = replaceRegion(html, TOC_BEGIN, TOC_END, built.toc, app.page);
  html = replaceRegion(html, BODY_BEGIN, BODY_END, built.body, app.page);
  writes.push([pagePath, html, app.page]);
}

// Gate: every caption the tables need must be in en.json, a parameter's help
// included - the app would show the raw key and no tooltip. Fix the string
// pack, not this script.
if (allMissing.length) {
  console.error(`❌ Missing in language/en.json:\n  ${[...new Set(allMissing)].join('\n  ')}`);
  process.exit(1);
}

for (const [p, html, label] of writes) {
  fs.writeFileSync(p, html, 'utf8');
  console.log(`✅ ${label} parameter tables regenerated`);
}